I'll create a calculator with both a command-line version and a GUI version using tkinter. Here are both implementations:

## 1. Command-Line Calculator

```python
class Calculator:
    """A simple calculator class for basic arithmetic operations."""

    @staticmethod
    def add(x, y):
        """Addition"""
        return x + y

    @staticmethod
    def subtract(x, y):
        """Subtraction"""
        return x - y

    @staticmethod
    def multiply(x, y):
        """Multiplication"""
        return x * y

    @staticmethod
    def divide(x, y):
        """Division"""
        if y == 0:
            return "Error: Division by zero!"
        return x / y

    @staticmethod
    def power(x, y):
        """Exponentiation"""
        return x ** y

    @staticmethod
    def modulo(x, y):
        """Modulo"""
        if y == 0:
            return "Error: Division by zero!"
        return x % y

def main():
    """Main function to run the calculator."""
    calc = Calculator()

    print("="*40)
    print("       PYTHON CALCULATOR")
    print("="*40)

    while True:
        print("\nSelect operation:")
        print("1. Add")
        print("2. Subtract")
        print("3. Multiply")
        print("4. Divide")
        print("5. Power")
        print("6. Modulo")
        print("7. Exit")

        choice = input("\nEnter choice (1-7): ")

        if choice == '7':
            print("Thank you for using the calculator!")
            break

        if choice not in ['1', '2', '3', '4', '5', '6']:
            print("Invalid input! Please try again.")
            continue

        try:
            num1 = float(input("Enter first number: "))
            num2 = float(input("Enter second number: "))
        except ValueError:
            print("Invalid input! Please enter valid numbers.")
            continue

        operations = {
            '1': (calc.add, '+'),
            '2': (calc.subtract, '-'),
            '3': (calc.multiply, '*'),
            '4': (calc.divide, '/'),
            '5': (calc.power, '^'),
            '6': (calc.modulo, '%')
        }

        operation, symbol = operations[choice]
        result = operation(num1, num2)

        print(f"\n{num1} {symbol} {num2} = {result}")
        print("-"*40)

if __name__ == "__main__":
    main()
```

## 2. GUI Calculator using Tkinter

