import tkinter as tk
from tkinter import ttk
import math

class GUICalculator:
    def __init__(self, root):
        self.root = root
        self.root.title("Python Calculator")
        self.root.geometry("400x600")
        self.root.resizable(False, False)

        # Variables
        self.current_number = ""
        self.first_number = None
        self.operation = None
        self.should_reset = False

        # Create widgets
        self.create_display()
        self.create_buttons()

    def create_display(self):
        """Create the display screen."""
        # Main display
        self.display_var = tk.StringVar(value="0")
        display = tk.Entry(self.root, textvariable=self.display_var, 
                          font=("Arial", 24), justify="right", state="readonly")
        display.grid(row=0, column=0, columnspan=4, padx=10, pady=20, 
                    sticky="ew", ipady=10)

        # History display
        self.history_var = tk.StringVar(value="")
        history = tk.Label(self.root, textvariable=self.history_var, 
                          font=("Arial", 12), anchor="e", fg="gray")
        history.grid(row=1, column=0, columnspan=4, padx=10, sticky="ew")

    def create_buttons(self):
        """Create calculator buttons."""
        # Button configuration
        button_config = {
            'font': ('Arial', 18),
            'width': 5,
            'height': 2
        }

        # Define buttons layout
        buttons = [
            ['C', 'CE', '⌫', '/'],
            ['7', '8', '9', '*'],
            ['4', '5', '6', '-'],
            ['1', '2', '3', '+'],
            ['±', '0', '.', '='],
            ['√', 'x²', '1/x', '%']
        ]

        # Create and place buttons
        for i, row in enumerate(buttons):
            for j, text in enumerate(row):
                if text in '0123456789':
                    cmd = lambda x=text: self.number_click(x)
                    bg = '#f0f0f0'
                elif text in ['+', '-', '*', '/', '=']:
                    if text == '=':
                        cmd = self.calculate
                        bg = '#4CAF50'
                    else:
                        cmd = lambda x=text: self.operation_click(x)
                        bg = '#ff9800'
                elif text == '.':
                    cmd = self.decimal_click
                    bg = '#f0f0f0'
                elif text == 'C':
                    cmd = self.clear_all
                    bg = '#f44336'
                elif text == 'CE':
                    cmd = self.clear_entry
                    bg = '#ff9800'
                elif text == '⌫':
                    cmd = self.backspace
                    bg = '#ff9800'
                elif text == '±':
                    cmd = self.toggle_sign
                    bg = '#2196F3'
                elif text == '√':
                    cmd = self.square_root
                    bg = '#2196F3'
                elif text == 'x²':
                    cmd = self.square
                    bg = '#2196F3'
                elif text == '1/x':
                    cmd = self.reciprocal
                    bg = '#2196F3'
                elif text == '%':
                    cmd = self.percentage
                    bg = '#2196F3'

                btn = tk.Button(self.root, text=text, command=cmd, 
                               bg=bg, fg='white' if bg != '#f0f0f0' else 'black',
                               **button_config)
                btn.grid(row=i+2, column=j, padx=5, pady=5, sticky="nsew")

        # Configure grid weights
        for i in range(4):
            self.root.columnconfigure(i, weight=1)
        for i in range(8):
            self.root.rowconfigure(i, weight=1)

    def number_click(self, number):
        """Handle number button clicks."""
        if self.should_reset:
            self.current_number = ""
            self.should_reset = False

        if self.current_number == "0":
            self.current_number = number
        else:
            self.current_number += number

        self.display_var.set(self.current_number)

    def operation_click(self, op):
        """Handle operation button clicks."""
        if self.current_number:
            if self.first_number is not None and not self.should_reset:
                self.calculate()
            self.first_number = float(self.current_number)
            self.operation = op
            self.history_var.set(f"{self.first_number} {op}")
            self.should_reset = True

    def calculate(self):
        """Perform the calculation."""
        if self.first_number is not None and self.current_number and self.operation:
            try:
                second_number = float(self.current_number)

                if self.operation == '+':
                    result = self.first_number + second_number
                elif self.operation == '-':
                    result = self.first_number - second_number
                elif self.operation == '*':
                    result = self.first_number * second_number
                elif self.operation == '/':
                    if second_number == 0:
                        self.display_var.set("Error: Div by 0")
                        self.should_reset = True
                        return
                    result = self.first_number / second_number

                # Format result
                if result == int(result):
                    result = int(result)

                self.history_var.set(f"{self.first_number} {self.operation} {second_number} =")
                self.display_var.set(str(result))
                self.current_number = str(result)
                self.first_number = None
                self.operation = None
                self.should_reset = True

            except Exception as e:
                self.display_var.set("Error")
                self.should_reset = True

    def clear_all(self):
        """Clear all data."""
        self.current_number = ""
        self.first_number = None
        self.operation = None
        self.display_var.set("0")
        self.history_var.set("")
        self.should_reset = False

    def clear_entry(self):
        """Clear current entry."""
        self.current_number = ""
        self.display_var.set("0")

    def backspace(self):
        """Remove last digit."""
        if not self.should_reset and self.current_number:
            self.current_number = self.current_number[:-1]
            if not self.current_number:
                self.current_number = "0"
            self.display_var.set(self.current_number)

    def decimal_click(self):
        """Add decimal point."""
        if self.should_reset:
            self.current_number = "0"
            self.should_reset = False

        if '.' not in self.current_number:
            if not self.current_number:
                self.current_number = "0"
            self.current_number += '.'
            self.display_var.set(self.current_number)

    def toggle_sign(self):
        """Toggle positive/negative."""
        if self.current_number and self.current_number != "0":
            if self.current_number.startswith('-'):
                self.current_number = self.current_number[1:]
            else:
                self.current_number = '-' + self.current_number
            self.display_var.set(self.current_number)

    def square_root(self):
        """Calculate square root."""
        try:
            if self.current_number:
                number = float(self.current_number)
                if number < 0:
                    self.display_var.set("Error: Invalid")
                else:
                    result = math.sqrt(number)
                    if result == int(result):
                        result = int(result)
                    self.display_var.set(str(result))
                    self.current_number = str(result)
                self.should_reset = True
        except:
            self.display_var.set("Error")
            self.should_reset = True

    def square(self):
        """Calculate square."""
        try:
            if self.current_number:
                number = float(self.current_number)
                result = number ** 2
                if result == int(result):
                    result = int(result)
                self.display_var.set(str(result))
                self.current_number = str(result)
                self.should_reset = True
        except:
            self.display_var.set("Error")
            self.should_reset = True

    def reciprocal(self):
        """Calculate reciprocal (1/x)."""
        try:
            if self.current_number:
                number = float(self.current_number)
                if number == 0:
                    self.display_var.set("Error: Div by 0")
                else:
                    result = 1 / number
                    self.display_var.set(str(result))
                    self.current_number = str(result)
                self.should_reset = True
        except:
            self.display_var.set("Error")
            self.should_reset = True

    def percentage(self):
        """Calculate percentage."""
        try:
            if self.current_number:
                number = float(self.current_number)
                result = number / 100
                self.display_var.set(str(result))
                self.current_number = str(result)
                self.should_reset = True
        except:
            self.display_var.set("Error")
            self.should_reset = True

def main():
    """Run the GUI calculator."""
    root = tk.Tk()
    calculator = GUICalculator(root)
    root.mainloop()

if __name__ == "__main__":
    main()
```

## 3. Scientific Calculator (Advanced)

```python
import math

class ScientificCalculator:
    """Scientific calculator with advanced functions."""

    @staticmethod
    def sin(x, mode='rad'):
        """Sine function"""
        if mode == 'deg':
            x = math.radians(x)
        return math.sin(x)

    @staticmethod
    def cos(x, mode='rad'):
        """Cosine function"""
        if mode == 'deg':
            x = math.radians(x)
        return math.cos(x)

    @staticmethod
    def tan(x, mode='rad'):
        """Tangent function"""
        if mode == 'deg':
            x = math.radians(x)
        return math.tan(x)

    @staticmethod
    def log(x, base=10):
        """Logarithm function"""
        if x <= 0:
            return "Error: Invalid input for logarithm"
        if base == 'e':
            return math.log(x)
        return math.log(x, base)

    @staticmethod
    def factorial(n):
        """Factorial function"""
        if n < 0:
            return "Error: Factorial of negative number"
        if n != int(n):
            return "Error: Factorial requires integer"
        return math.factorial(int(n))

    @staticmethod
    def combination(n, r):
        """Combination (nCr)"""
        if n < 0 or r < 0 or r > n:
            return "Error: Invalid input for combination"
        return math.factorial(int(n)) // (math.factorial(int(r)) * math.factorial(int(n-r)))

    @staticmethod
    def permutation(n, r):
        """Permutation (nPr)"""
        if n < 0 or r < 0 or r > n:
            return "Error: Invalid input for permutation"
        return math.factorial(int(n)) // math.factorial(int(n-r))

# Example usage
if __name__ == "__main__":
    calc = ScientificCalculator()

    # Test scientific functions
    print(f"sin(30°) = {calc.sin(30, 'deg'):.4f}")
    print(f"cos(60°) = {calc.cos(60, 'deg'):.4f}")
    print(f"log(100) = {calc.log(100)}")
    print(f"5! = {calc.factorial(5)}")
    print(f"10C3 = {calc.combination(10, 3)}")
    print(f"10P3 = {calc.permutation(10, 3)}")
```

Choose the calculator that best fits your needs:
- **Command-line calculator**: Simple and easy to use in terminal
- **GUI calculator**: User-friendly interface with mouse support
- **Scientific calculator**: Advanced mathematical functions

To run any of these calculators, save the code to a `.py` file and run it with Python. The GUI calculator requires the tkinter library, which comes pre-installed with most Python distributions.

